/*
 * Public startup_store_load / startup_store_save against a memory FRAM.
 *
 * The expected bytes come from independent sources: the golden slot/image
 * literals of CONTRACT-VECTOR.json (generated by Python zlib.crc32) and the
 * separate SSP1 fixture encoder in startup_fixtures.h. No private offset,
 * decoder or token hook is reachable from here.
 *
 * Failure model under test: a save rewrites only the inactive slot and commits
 * last, so a cut at any point must leave a complete old or a complete new
 * record. The previous slot and the fresh record are the only two outcomes.
 */
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "framework.h"
#include "FRAM/MB85RS256B.h"
#include "startup/startup_store.h"
#include "startup_fixtures.h"

/* CONTRACT-VECTOR.json: boot_count 0, adcs_mask 0, unarmed, sequence 1. */
static const char *const GOLDEN_SLOT = "535350310100000000000040771b00421c4937a5";
static const char *const GOLDEN_IMAGE =
    "0000000000000000"
    "535350310100000000000040771b00421c4937a5"
    "535350310100000000000040771b00421c4937a5";
/* Published by a save of INITIAL_CHECKS/0 attempts/unarmed/remaining 1799000. */
static const char *const SAVED_AFTER_GOLDEN = "535350310200000000000058731b00efad0f3ca5";

#define FRAM_BYTES 32768u
#define SENTINEL 0x5Au

static uint8_t fram[FRAM_BYTES];
static bool enabled;
static bool fail_read;
static bool fail_write_enable;
static bool fail_write_disable;
static bool ignore_writes;
static bool corrupt_readback;
static long cut_budget = -1; /* bytes that survive a modeled power loss, -1 disabled */
static bool power_lost;
static unsigned write_disable_calls;
static unsigned fail_write_disable_at; /* 1-based write-disable call that reports failure */

static void require(bool condition, const char *why) {
    if (!condition) {
        fprintf(stderr, "startup store harness: %s\n", why);
        exit(2);
    }
}

static void hex_to_bytes(const char *hex, uint8_t *out, size_t size) {
    require(strlen(hex) == size * 2, "hex literal length");
    for (size_t i = 0; i < size; ++i) {
        unsigned value = 0;
        require(sscanf(hex + 2 * i, "%2x", &value) == 1, "hex literal digit");
        out[i] = (uint8_t)value;
    }
}

static void media_reset(void) {
    memset(fram, SENTINEL, sizeof(fram));
    enabled = false;
    fail_read = fail_write_enable = fail_write_disable = false;
    ignore_writes = corrupt_readback = false;
    cut_budget = -1;
    power_lost = false;
    write_disable_calls = 0;
    fail_write_disable_at = 0;
    /* Boot counter and ADCS mask: unrelated storage Startup must never rewrite. */
    const uint8_t headers[8] = {0, 0, 0, 0, 0, 0, 0, 0};
    memcpy(fram, headers, sizeof(headers));
}

/* The contract image covers bytes 0..47: boot counter, ADCS mask, then both slots. */
static void media_golden_image(void) {
    uint8_t image[SSP1_IMAGE_SIZE];
    hex_to_bytes(GOLDEN_IMAGE, image, sizeof(image));
    memcpy(fram, image, sizeof(image)); /* addresses 0..47 are byte offsets too */
}

static void media_place_slot(uint8_t slot, uint32_t sequence, uint8_t state, uint8_t attempts,
                             bool armed, uint32_t remaining) {
    ssp1_build(fram + SSP1_ADDRESS + slot * SSP1_SLOT_SIZE, sequence, state, attempts, armed, remaining);
}

static const uint8_t *media_slot(uint8_t slot) {
    return fram + SSP1_ADDRESS + slot * SSP1_SLOT_SIZE;
}

static bool bytes_equal(const uint8_t *left, const uint8_t *right, size_t size) {
    return memcmp(left, right, size) == 0;
}

static void require_golden_slot(uint8_t slot) {
    uint8_t expected[SSP1_SLOT_SIZE];
    hex_to_bytes(GOLDEN_SLOT, expected, sizeof(expected));
    require(bytes_equal(media_slot(slot), expected, sizeof(expected)), "golden slot bytes");
}

static void require_unrelated_media_untouched(void) {
    for (size_t address = 0; address < SSP1_ADDRESS; ++address) require(fram[address] == 0, "boot/ADCS preserved");
    for (size_t address = SSP1_ADDRESS + SSP1_IMAGE_SIZE; address < FRAM_BYTES; ++address) {
        require(fram[address] == SENTINEL, "bytes after the Startup slots untouched");
    }
}

/***************************** FRAM boundary model ***************************/

bool FRAM_readData(uint16_t address, uint8_t *buffer, uint16_t size) {
    if (fail_read) return false;
    require(address + size <= FRAM_BYTES, "FRAM read bounds");
    memcpy(buffer, fram + address, size);
    if (corrupt_readback) buffer[0] ^= 0x01u;
    return true;
}

bool FRAM_writeEnable(void) {
    enabled = !fail_write_enable;
    return enabled;
}

bool FRAM_writeDisable(void) {
    enabled = false;
    ++write_disable_calls;
    if (fail_write_disable_at != 0 && write_disable_calls == fail_write_disable_at) return false;
    return !fail_write_disable;
}

bool FRAM_writeData(uint16_t address, uint8_t *data, uint16_t size) {
    require(address >= SSP1_ADDRESS && address + size <= SSP1_ADDRESS + SSP1_IMAGE_SIZE,
            "Startup storage writes stay inside bytes 8..47");
    require(size > 0, "non-empty write");
    if (!enabled) return false;
    if (cut_budget >= 0) {
        if (power_lost) return false;
        size_t applied = (size_t)cut_budget < size ? (size_t)cut_budget : size;
        memcpy(fram + address, data, applied);
        cut_budget -= (long)applied;
        if (applied < size) {
            power_lost = true;
            return false;
        }
        if (cut_budget == 0) power_lost = true;
        return true;
    }
    if (ignore_writes) return true;
    memcpy(fram + address, data, size);
    return true;
}

/***************************** Scenarios *************************************/

/* Save a record described inline; a compound literal keeps it an lvalue. */
#define SAVE_STATE(v_state, v_attempts, v_armed, v_remaining)                                  \
    startup_store_save(&(StartupStoreState){.resume_state = (v_state),                          \
                                            .attempts_used = (v_attempts),                      \
                                            .armed = (v_armed),                                 \
                                            .remaining_ms = (v_remaining)})

static void test_golden_image_round_trip_publishes_other_slot(void) {
    media_reset();
    media_golden_image();
    StartupStoreState state = {0};
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_OK);
    TEST_ASSERT(state.resume_state == INITIAL_CHECKS);
    TEST_ASSERT(state.attempts_used == 0);
    TEST_ASSERT(state.armed == false);
    TEST_ASSERT(state.remaining_ms == 1800000u);
    require_golden_slot(0);
    require_golden_slot(1);

    TEST_ASSERT(SAVE_STATE(INITIAL_CHECKS, 0, false, 1799000u) == STARTUP_STORE_OK);
    /* The active slot is untouched; the inactive slot holds the exact contract bytes. */
    require_golden_slot(0);
    uint8_t expected[SSP1_SLOT_SIZE];
    hex_to_bytes(SAVED_AFTER_GOLDEN, expected, sizeof(expected));
    require(bytes_equal(media_slot(1), expected, sizeof(expected)), "inactive slot holds the new record");
    require_unrelated_media_untouched();

    /* The published record is what the next boot loads. */
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_OK);
    TEST_ASSERT(state.remaining_ms == 1799000u);
    TEST_ASSERT(state.resume_state == INITIAL_CHECKS);

    /* Slot A now becomes the inactive slot for the next publication. */
    TEST_ASSERT(SAVE_STATE(INITIAL_CHECKS, 0, false, 1700000u) == STARTUP_STORE_OK);
    TEST_ASSERT(bytes_equal(media_slot(1), expected, sizeof(expected)));
    Ssp1Record slot_a;
    TEST_ASSERT(ssp1_read(media_slot(0), &slot_a));
    TEST_ASSERT(slot_a.sequence == 3);
    TEST_ASSERT(slot_a.remaining == 1700000u);
    require_unrelated_media_untouched();
}

static void test_single_valid_slot_is_used_and_pair_resolution(void) {
    StartupStoreState state = {0};

    media_reset();
    media_place_slot(0, 4, WAIT_POWER_ON, 2, true, 0);
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_OK);
    TEST_ASSERT(state.resume_state == WAIT_POWER_ON && state.attempts_used == 2 && state.armed);

    media_reset();
    media_place_slot(1, 5, MAIN_OPS, 7, true, 0);
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_OK);
    TEST_ASSERT(state.resume_state == MAIN_OPS && state.attempts_used == 7);

    /* Higher sequence wins, in either slot order. */
    media_reset();
    media_place_slot(0, 6, WAIT_POWER_ON, 1, true, 0);
    media_place_slot(1, 7, WAITING_FOR_UPLINK, 2, true, STARTUP_RETRY_MS);
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_OK);
    TEST_ASSERT(state.resume_state == WAITING_FOR_UPLINK && state.attempts_used == 2);

    media_reset();
    media_place_slot(0, 8, WAITING_FOR_UPLINK, 3, true, STARTUP_RETRY_MS);
    media_place_slot(1, 7, WAIT_POWER_ON, 1, true, 0);
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_OK);
    TEST_ASSERT(state.resume_state == WAITING_FOR_UPLINK && state.attempts_used == 3);

    /* Equal sequences must be byte-identical; then the next save targets slot B. */
    media_reset();
    media_golden_image();
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_OK);
    TEST_ASSERT(SAVE_STATE(WAIT_POWER_ON, 0, true, 0) == STARTUP_STORE_OK);
    require_golden_slot(0);
    Ssp1Record slot_b;
    TEST_ASSERT(ssp1_read(media_slot(1), &slot_b));
    TEST_ASSERT(slot_b.sequence == 2 && slot_b.state == WAIT_POWER_ON && slot_b.flags == 0x01u);

    media_reset();
    media_place_slot(0, 9, WAIT_POWER_ON, 3, true, 0);
    media_place_slot(1, 9, WAIT_POWER_ON, 4, true, 0);
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_INVALID);

    media_reset();
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_INVALID);
}

static void test_malformed_records_are_rejected(void) {
    uint8_t slot[SSP1_SLOT_SIZE];
    StartupStoreState state = {0};

    /* Mutations of the golden slot: no independent encoder involved. */
    hex_to_bytes(GOLDEN_SLOT, slot, sizeof(slot));
    slot[SSP1_COMMIT] = 0x00u;
    media_reset();
    memcpy(fram + SSP1_ADDRESS, slot, sizeof(slot));
    memcpy(fram + SSP1_ADDRESS + SSP1_SLOT_SIZE, slot, sizeof(slot));
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_INVALID);

    hex_to_bytes(GOLDEN_SLOT, slot, sizeof(slot));
    slot[SSP1_TAG + 3] = '2'; /* "SSP2", not the SSP1 tag */
    media_reset();
    memcpy(fram + SSP1_ADDRESS, slot, sizeof(slot));
    memcpy(fram + SSP1_ADDRESS + SSP1_SLOT_SIZE, slot, sizeof(slot));
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_INVALID);

    hex_to_bytes(GOLDEN_SLOT, slot, sizeof(slot));
    slot[0] ^= 0x01u; /* CRC no longer covers the tag */
    media_reset();
    memcpy(fram + SSP1_ADDRESS, slot, sizeof(slot));
    memcpy(fram + SSP1_ADDRESS + SSP1_SLOT_SIZE, slot, sizeof(slot));
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_INVALID);

    /* Structurally well-formed records whose fields are out of contract. */
    struct {
        uint32_t sequence;
        uint8_t state;
        uint8_t attempts;
        bool armed;
        uint32_t remaining;
        const char *why;
    } const invalid[] = {
        {1, INITIAL_CHECKS, 1, true, 0, "initial checks with a consumed attempt"},
        {1, INITIAL_CHECKS, 0, true, STARTUP_INHIBIT_MS + 1u, "inhibit longer than the inhibit"},
        {1, WAIT_POWER_ON, 0, true, 1, "power-on wait with time remaining"},
        {1, WAIT_POWER_ON, 0, false, 0, "power-on wait while unarmed"},
        {1, WAITING_FOR_UPLINK, 0, true, 0, "retry wait without an attempt"},
        {1, WAITING_FOR_UPLINK, 8, true, 0, "attempts above the limit"},
        {1, WAITING_FOR_UPLINK, 6, true, STARTUP_RETRY_MS + 1u, "two-day wait too long"},
        {1, WAITING_FOR_UPLINK, 7, true, STARTUP_WEEKLY_MS + 1u, "weekly wait too long"},
        {1, WAITING_FOR_UPLINK, 7, false, STARTUP_WEEKLY_MS, "retry wait while unarmed"},
        {1, SAT_TO_GROUND_1, 1, true, 1, "handshake entry with time remaining"},
        {1, SAT_TO_GROUND_1, 1, false, 0, "handshake entry while unarmed"},
        {1, MAIN_OPS, 1, true, 1, "main ops with time remaining"},
        {1, MAIN_OPS, 1, false, 0, "main ops while unarmed"},
        {1, GROUND_TO_SAT_1, 1, true, 0, "transient handshake state persisted"},
        {1, SAT_TO_GROUND_2, 1, true, 0, "transient ready state persisted"},
        {1, DIAGNOSTICS_MODE, 1, true, 0, "diagnostics state persisted"},
        {0, INITIAL_CHECKS, 0, true, 0, "sequence zero is not a publication"},
    };
    for (size_t i = 0; i < sizeof(invalid) / sizeof(invalid[0]); ++i) {
        media_reset();
        media_place_slot(0, invalid[i].sequence, invalid[i].state, invalid[i].attempts,
                         invalid[i].armed, invalid[i].remaining);
        media_place_slot(1, invalid[i].sequence, invalid[i].state, invalid[i].attempts,
                         invalid[i].armed, invalid[i].remaining);
        if (startup_store_load(&state) != STARTUP_STORE_INVALID) {
            printf("  accepted: %s\n", invalid[i].why);
            TEST_ASSERT(false);
        } else {
            TEST_ASSERT(true);
        }
    }

    /* Reserved flag bits are not part of the contract. */
    media_reset();
    ssp1_build(fram + SSP1_ADDRESS, 1, WAIT_POWER_ON, 0, true, 0);
    fram[SSP1_ADDRESS + SSP1_FLAGS] = 0x03u;
    {
        uint8_t fixed[SSP1_SLOT_SIZE];
        memcpy(fixed, fram + SSP1_ADDRESS, sizeof(fixed));
        ssp1_le(fixed + SSP1_CRC, ssp1_crc(fixed, SSP1_CRC), 4);
        memcpy(fram + SSP1_ADDRESS + SSP1_SLOT_SIZE, fixed, sizeof(fixed));
        memcpy(fram + SSP1_ADDRESS, fixed, sizeof(fixed));
    }
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_INVALID);

    /* Positive controls for the same field checks. */
    media_reset();
    media_place_slot(0, 2, WAITING_FOR_UPLINK, 6, true, STARTUP_RETRY_MS);
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_OK);
    media_reset();
    media_place_slot(1, 3, WAITING_FOR_UPLINK, 7, true, STARTUP_WEEKLY_MS);
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_OK);
    media_reset();
    media_place_slot(0, 4, INITIAL_CHECKS, 0, true, STARTUP_INHIBIT_MS);
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_OK);
    TEST_ASSERT(startup_store_retry_ms(1) == STARTUP_RETRY_MS);
    TEST_ASSERT(startup_store_retry_ms(6) == STARTUP_RETRY_MS);
    TEST_ASSERT(startup_store_retry_ms(7) == STARTUP_WEEKLY_MS);
}

static void test_interrupted_save_always_leaves_old_or_new_record(void) {
    /* 21 written bytes: 1 invalidate, 19 payload, 1 commit. */
    for (long cut = 0; cut <= 21; ++cut) {
        media_reset();
        media_golden_image();
        StartupStoreState state = {0};
        require(startup_store_load(&state) == STARTUP_STORE_OK, "media loadable");
        cut_budget = cut;
        StartupStoreResult result = SAVE_STATE(INITIAL_CHECKS, 0, false, 1799000u);
        bool published = result == STARTUP_STORE_OK;
        cut_budget = -1;
        power_lost = false;

        require(startup_store_load(&state) == STARTUP_STORE_OK, "cut media still has a complete record");
        bool old = state.resume_state == INITIAL_CHECKS && state.remaining_ms == 1800000u;
        bool fresh = state.resume_state == INITIAL_CHECKS && state.remaining_ms == 1799000u;
        if (!(old || fresh)) {
            printf("  cut %ld produced neither complete record\n", cut);
            TEST_ASSERT(false);
            continue;
        }
        /* A reported success must be readable as the new record; a failure must
         * never be reported after the new record was already complete. */
        TEST_ASSERT(!published || fresh);
        TEST_ASSERT(cut < 21 ? old : (cut == 21 ? fresh : false));
        require_golden_slot(0);
        require_unrelated_media_untouched();
    }
}

static void test_commit_written_but_response_lost_is_recovered_as_new(void) {
    media_reset();
    media_golden_image();
    StartupStoreState state = {0};
    require(startup_store_load(&state) == STARTUP_STORE_OK, "media loadable");
    /* Writes are: invalidate, payload, commit. The third one lands on the media
     * but its write-disable reports failure, so the result is uncertain. */
    fail_write_disable_at = 3;
    TEST_ASSERT(SAVE_STATE(INITIAL_CHECKS, 0, false, 1799000u) == STARTUP_STORE_IO);
    fail_write_disable_at = 0;
    /* The complete new record is a legitimate recovery point: an uncertain result
     * is consumed as a committed record, never replayed as an uncommitted one. */
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_OK);
    TEST_ASSERT(state.resume_state == INITIAL_CHECKS && state.remaining_ms == 1799000u);
    Ssp1Record slot_b;
    TEST_ASSERT(ssp1_read(media_slot(1), &slot_b));
    TEST_ASSERT(slot_b.sequence == 2);
    require_golden_slot(0);
}

static void test_io_faults_report_error_and_keep_active_slot(void) {
    media_reset();
    media_golden_image();
    StartupStoreState state = {0};
    require(startup_store_load(&state) == STARTUP_STORE_OK, "media loadable");

    fail_write_enable = true;
    TEST_ASSERT(SAVE_STATE(INITIAL_CHECKS, 0, false, 1799000u) == STARTUP_STORE_IO);
    fail_write_enable = false;
    require_golden_slot(0);

    fail_write_disable = true;
    TEST_ASSERT(SAVE_STATE(INITIAL_CHECKS, 0, false, 1799000u) == STARTUP_STORE_IO);
    fail_write_disable = false;
    require_golden_slot(0);

    ignore_writes = true;
    TEST_ASSERT(SAVE_STATE(INITIAL_CHECKS, 0, false, 1799000u) == STARTUP_STORE_IO);
    ignore_writes = false;
    require_golden_slot(0);

    corrupt_readback = true;
    TEST_ASSERT(SAVE_STATE(INITIAL_CHECKS, 0, false, 1799000u) == STARTUP_STORE_IO);
    corrupt_readback = false;

    fail_read = true;
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_IO);
    TEST_ASSERT(SAVE_STATE(INITIAL_CHECKS, 0, false, 1799000u) == STARTUP_STORE_IO);
    fail_read = false;

    /* The active record survived every fault and a retry still publishes. */
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_OK);
    TEST_ASSERT(state.remaining_ms == 1800000u);
    TEST_ASSERT(SAVE_STATE(INITIAL_CHECKS, 0, false, 1799000u) == STARTUP_STORE_OK);
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_OK);
    TEST_ASSERT(state.remaining_ms == 1799000u);
    require_golden_slot(0);
    require_unrelated_media_untouched();
}

static void test_sequence_exhaustion_refuses_to_wrap(void) {
    media_reset();
    media_place_slot(0, UINT32_MAX, INITIAL_CHECKS, 0, false, 1000);
    media_place_slot(1, UINT32_MAX, INITIAL_CHECKS, 0, false, 1000);
    uint8_t before_a[SSP1_SLOT_SIZE];
    uint8_t before_b[SSP1_SLOT_SIZE];
    memcpy(before_a, media_slot(0), sizeof(before_a));
    memcpy(before_b, media_slot(1), sizeof(before_b));
    StartupStoreState state = {0};
    TEST_ASSERT(startup_store_load(&state) == STARTUP_STORE_OK);
    TEST_ASSERT(SAVE_STATE(INITIAL_CHECKS, 0, false, 900) == STARTUP_STORE_EXHAUSTED);
    TEST_ASSERT(bytes_equal(media_slot(0), before_a, sizeof(before_a)));
    TEST_ASSERT(bytes_equal(media_slot(1), before_b, sizeof(before_b)));
}

int main(void) {
    TEST_SUITE("startup store: exact SSP1 record and two-slot load/save");
    RUN_TEST(test_golden_image_round_trip_publishes_other_slot);
    RUN_TEST(test_single_valid_slot_is_used_and_pair_resolution);
    RUN_TEST(test_malformed_records_are_rejected);
    RUN_TEST(test_interrupted_save_always_leaves_old_or_new_record);
    RUN_TEST(test_commit_written_but_response_lost_is_recovered_as_new);
    RUN_TEST(test_io_faults_report_error_and_keep_active_slot);
    RUN_TEST(test_sequence_exhaustion_refuses_to_wrap);
    TEST_RESULTS();
}
